// Format the Error Trigger payload as a Telegram HTML message.
const d = $input.first().json || {};
const exec = d.execution || {};
const trig = d.trigger || {};
const wf = d.workflow || {};
const err = exec.error || trig.error || {};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let message = err.message || err.description || 'Unknown error';
if (message.length > 1500) message = message.slice(0, 1497) + '...';
const failedNode = exec.lastNodeExecuted || (err.node && err.node.name) || (trig.error && trig.error.node && trig.error.node.name) || '—';

const lines = [
  '🚨 <b>n8n workflow failed</b>',
  '',
  `⚙️ <b>Workflow:</b> ${esc(wf.name || wf.id || '—')}`,
  `🧩 <b>Failed node:</b> ${esc(failedNode)}`,
  `❌ <b>Error:</b> <code>${esc(message)}</code>`,
  `🕒 <b>Mode:</b> ${esc(exec.mode || trig.mode || '—')}`,
];
if (exec.url) lines.push(`🔗 <a href="${esc(exec.url)}">Open execution ${esc(exec.id || '')}</a>`);
else if (exec.id) lines.push(`🆔 Execution: <code>${esc(exec.id)}</code>`);
else lines.push('(Error happened in the trigger, so there is no execution to open.)');

return [{ json: { text: lines.join('\n') } }];
